import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * Generates every artifact derived from `src/languages/*.ts`:
 *
 * - `src/domain/language/catalog.ts` (eager catalog array)
 * - `src/domain/language/registry.ts` (slug/extension index + dynamic import map)
 * - `src/index.ts` language-exports block (between auto-generated markers)
 * - `package.json` `exports` map (root/api/i18n/detect entries + one subpath per language)
 * - `README.md` Supported Languages count and table
 *
 * Run with `npm run codegen`. CI fails if the generated output differs from
 * the committed files.
 */

const languagesDir = 'src/languages';
const catalogPath = 'src/domain/language/catalog.ts';
const registryPath = 'src/domain/language/registry.ts';
const indexPath = 'src/index.ts';
const packageJsonPath = 'package.json';
const readmePath = 'README.md';
const generatedHeader =
  '// Generated by scripts/generate-language-artifacts.mjs — do not edit manually. Run `npm run codegen`.';

const extractField = (source, pattern, file) => {
  const match = source.match(pattern);

  if (!match) {
    throw new Error(`Could not extract ${pattern} from ${file}`);
  }

  return match;
};

const parseLanguageFile = (file) => {
  const slug = file.replace(/\.ts$/, '');
  const source = readFileSync(join(languagesDir, file), 'utf8');
  const [, exportName] = extractField(source, /export const (\w+)/, file);
  const [, extensionsBody] = extractField(source, /^ {2}extensions: \[([\s\S]*?)\]/m, file);
  const extensions = [...extensionsBody.matchAll(/(['"])((?:(?!\1).)*)\1/g)].map(
    (match) => match[2],
  );
  const [, , version] = extractField(source, /^ {2}version: (['"])((?:(?!\1).)*)\1/m, file);
  const [, , logo] = extractField(source, /^ {2}logo: (['"])((?:(?!\1).)*)\1/m, file);
  const [, , name] = extractField(source, /en: \{\s*\n\s*name: (['"])((?:(?!\1).)*)\1/, file);

  if (extensions.length === 0) {
    throw new Error(`${file} has no extensions`);
  }

  return { slug, exportName, extensions, version, logo, name };
};

const languages = readdirSync(languagesDir)
  .filter((file) => file.endsWith('.ts'))
  .map(parseLanguageFile)
  .sort((first, second) => (first.slug < second.slug ? -1 : 1));

const quoteKey = (slug) => (/^[a-z][a-z0-9]*$/.test(slug) ? slug : `'${slug}'`);

// --- src/domain/language/catalog.ts ---

const catalogImports = languages
  .map(({ slug, exportName }) => `import { ${exportName} } from '@/languages/${slug}';`)
  .join('\n');
const catalogArray = languages.map(({ exportName }) => `  ${exportName},`).join('\n');

writeFileSync(
  catalogPath,
  `${generatedHeader}
${catalogImports}
import type { Language } from '@/types';

/** Eager in-memory catalog of every language, ordered alphabetically by slug. */
export const languages = [
${catalogArray}
] as const satisfies readonly Language[];
`,
);

// --- src/domain/language/registry.ts ---

const indexEntries = languages
  .map(
    ({ slug, extensions }) =>
      `  { slug: '${slug}', extensions: [${extensions.map((extension) => `'${extension}'`).join(', ')}] },`,
  )
  .join('\n');
const loaderEntries = languages
  .map(
    ({ slug, exportName }) =>
      `  ${quoteKey(slug)}: async () => (await import('@/languages/${slug}')).${exportName},`,
  )
  .join('\n');

writeFileSync(
  registryPath,
  `${generatedHeader}
import type { Language } from '@/types';

export interface LanguageIndexEntry {
  slug: string;
  extensions: readonly string[];
}

/** Lightweight slug and extension index used by lazy filename detection. */
export const languageIndex = [
${indexEntries}
] as const satisfies readonly LanguageIndexEntry[];

export type LanguageSlug = (typeof languageIndex)[number]['slug'];

/** Explicit dynamic import map for every language module. */
export const languageLoaders: Record<LanguageSlug, () => Promise<Language>> = {
${loaderEntries}
};

/** Dynamically imports a language module by slug. */
export const loadLanguage = (slug: string) => languageLoaders[slug as LanguageSlug]?.();
`,
);

// --- src/index.ts language-exports block ---

const indexSource = readFileSync(indexPath, 'utf8');
const startMarker = '// <auto-generated:language-exports>';
const endMarker = '// </auto-generated:language-exports>';
const startIndex = indexSource.indexOf(startMarker);
const endIndex = indexSource.indexOf(endMarker);

if (startIndex === -1 || endIndex === -1) {
  throw new Error(`Missing auto-generated language-exports markers in ${indexPath}`);
}

const startLineEnd = indexSource.indexOf('\n', startIndex);
const languageExports = languages
  .map(({ slug, exportName }) => `export { ${exportName} } from '@/languages/${slug}';`)
  .join('\n');

writeFileSync(
  indexPath,
  `${indexSource.slice(0, startLineEnd + 1)}${languageExports}\n${indexSource.slice(endIndex)}`,
);

// --- package.json exports ---

const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf8'));
const subpathEntry = (path) => ({
  types: `./dist/${path}.d.ts`,
  import: `./dist/${path}.js`,
  require: `./dist/${path}.cjs`,
});

packageJson.exports = {
  '.': subpathEntry('index'),
  './api': subpathEntry('api'),
  './i18n': subpathEntry('i18n'),
  './detect': subpathEntry('detect'),
  './detect-slugs': subpathEntry('detect-slugs'),
  ...Object.fromEntries(
    languages.map(({ slug }) => [`./${slug}`, subpathEntry(`languages/${slug}`)]),
  ),
};

writeFileSync(packageJsonPath, `${JSON.stringify(packageJson, null, 2)}\n`);

// --- README.md Supported Languages section ---

const readme = readFileSync(readmePath, 'utf8');
const sectionHeading = '## Supported Languages';
const nextHeading = '## Development';
const sectionStart = readme.indexOf(sectionHeading);
const sectionEnd = readme.indexOf(nextHeading);

if (sectionStart === -1 || sectionEnd === -1) {
  throw new Error(`Could not locate the Supported Languages section in ${readmePath}`);
}

const tableRows = languages
  .map(({ slug, extensions, version, logo, name }) => {
    const extensionList = extensions.map((extension) => `\`${extension}\``).join(', ');

    return `| <img src="${logo}" alt="${name} logo" width="24" height="24"> | ${name} | \`${slug}\` | ${extensionList} | \`${version}\` | \`code-languages/${slug}\` |`;
  })
  .join('\n');
const section = `${sectionHeading}

The catalog currently includes ${languages.length} language entries. Each row can be imported directly
from its package subpath.

| Logo | Language | Slug | Extensions | Version | Import |
|---|---|---|---|---|---|
${tableRows}

`;

writeFileSync(readmePath, `${readme.slice(0, sectionStart)}${section}${readme.slice(sectionEnd)}`);

console.log(
  `Generated catalog, registry, index exports, package.json exports, and README table for ${languages.length} languages.`,
);
